#!/usr/bin/env bash
# One-shot, self-contained installer for the cursor-accent setup on Omarchy.
#
# Installs everything needed so the pointer is a Bibata cursor recolored to
# the active Omarchy theme's accent (Hyprland + GTK/Qt/X via XCursor), applied
# on login and on every theme switch. Ships with a `plugin/` bundle folder next
# to it (the whole cursor-accent plugin, patched recolor.py, no .git) PLUS the
# embedded xcursorgen binary, hooks installer, env + gsettings wiring, and the
# final build/apply. Fully OFFLINE - no clone, no internet, no /tmp, no Dots,
# no WinSur assumptions: works on a fresh Omarchy install.
#
# Idempotent: safe to re-run any time (re-asserts patches/hooks/env after e.g.
# `omarchy plugin update` overwrites the tracked recolor.py).
#
#   bash install.sh            # install everything, size 16
#   CURSOR_SIZE=20 bash install.sh
#
# OFFLINE: this installer ships with a `plugin/` folder next to it (the
# entire cursor-accent plugin, patched recolor.py included, no .git). No
# internet is needed - the plugin is copied into Omarchy from that folder.
set -euo pipefail

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
BUNDLE="$SCRIPT_DIR/plugin"

SIZE="${CURSOR_SIZE:-16}"
PLUGIN_ID="io.github.smoothpixels.cursor-accent"
PLUGIN_DIR="$HOME/.config/omarchy/plugins/$PLUGIN_ID"
STATE_DIR="$HOME/.local/state/cursor-accent"
ENVS="$HOME/.config/hypr/envs.lua"
AUTOSTART="$HOME/.config/hypr/autostart.lua"
CURSOR_NAME="Omarchy-Accent"
ICONDIR="$HOME/.local/share/icons/$CURSOR_NAME"

log() { printf '\033[1;32m==>\033[0m %s\n' "$*"; }
die() { printf '\033[1;31mERROR:\033[0m %s\n' "$*" >&2; exit 1; }

command -v omarchy >/dev/null || die "omarchy CLI not found"
command -v python3 >/dev/null || die "python3 not found"
command -v rsvg-convert >/dev/null || die "rsvg-convert missing - install librsvg"
command -v hyprctl >/dev/null || die "hyprctl not found (is Hyprland your session?)"
[ -d "$BUNDLE" ] || die "plugin bundle missing: expected $BUNDLE (keep this folder next to install.sh)"

# ---------------------------------------------------------------- xcursorgen
# Embedded binary (xorg-xcursorgen 1.0.9-1, x86_64). Needs libx11/libxcursor/
# libpng/glibc - all present on an Omarchy base. The X11 build path of
# recolor.py requires it; hooks may not have ~/.local/bin on PATH.
if [ ! -x "$HOME/.local/bin/xcursorgen" ]; then
  mkdir -p "$HOME/.local/bin"
  printf '%s' '' | base64 -d > "$HOME/.local/bin/xcursorgen"
  chmod 755 "$HOME/.local/bin/xcursorgen"
  log "restored xcursorgen to ~/.local/bin"
else
  log "xcursorgen already present at ~/.local/bin"
fi

# ------------------------------------------------------------- plugin install
# Offline install: copy the whole bundled plugin folder (no .git) into
# Omarchy's plugins dir, then enable it. No network involved.
if [ ! -f "$PLUGIN_DIR/manifest.json" ]; then
  log "installing cursor-accent plugin from bundle (offline)..."
  mkdir -p "$HOME/.config/omarchy/plugins"
  rsync -a --delete "$BUNDLE/" "$PLUGIN_DIR/" 2>/dev/null || cp -a "$BUNDLE/." "$PLUGIN_DIR/"
  log "rescanPlugins (so the shell discovers the copied folder)..."
  omarchy-shell shell rescanPlugins >/dev/null 2>&1 || true
  log "enabling plugin..."
  omarchy plugin enable "$PLUGIN_ID" >/dev/null 2>&1 || true
else
  log "plugin already present, ensuring enabled..."
  omarchy plugin enable "$PLUGIN_ID" >/dev/null 2>&1 || true
fi

# --------------------------------------------------- patched recolor.py drop
# Overwrites whatever omarchy cloned/updated so the 4 patches always apply:
#   1. ~/.local/bin on PATH (hooks find xcursorgen)
#   2. one-pass --hypr --x11 --x11-symlink adwaita build (hyprcursor + XCursor)
#   3. fingerprint cache (~/.local/state/cursor-accent/fingerprint) so the
#      post-boot hook re-applies in ~0.3s instead of a ~52s rebuild
#   4. ATOMIC install (.Omarchy-Accent.new -> rename swap): the old
#      rmtree-then-copytree could leave the theme dir empty mid-swap, and a
#      running Hyprland reading a shape then got a NULL cairo surface and
#      SEGV'd in CCursorBuffer (crash report 2026-10-09).
log "writing patched recolor.py..."
mkdir -p "$PLUGIN_DIR"
cat > "$PLUGIN_DIR/recolor.py" <<'RLR_EOF'
#!/usr/bin/env python3
"""Recolors a Bibata hyprcursor theme, installs it, and applies it live.

Colors come from one of three modes, read from config.json:
  "theme" (default): follow the active Omarchy theme's colors.toml
    body   <- dark_background / background
    accent <- accent
    watch  <- darker_background / background
  "fixed": always use config.json's fixed_color for the outline, ignoring
    whatever the active theme is.
  "off": revert to the system's own default cursor (skips the whole build).

Shape comes from config.json's "shape": "modern" (default, rounded) or
"original" (classic sharp-edged pointer). Both are pre-defined render
targets in the vendored bibata_cursor's config/render.json.

Usage: recolor.py [theme-name]   (theme-name is cosmetic/logging only; theme
mode always reads whatever is currently staged, since that's what
omarchy-theme-set has already switched to by the time its hook runs.)

Paths are resolved relative to this file, not hardcoded, so this works
whether it's run from a git checkout or from an installed
~/.config/omarchy/plugins/<id>/ copy. User-editable state (config.json)
lives outside that directory, in ~/.local/state, so `omarchy plugin update`
(which re-syncs the plugin's own folder from git) never touches it.
"""
import fcntl
import json
import os
import shutil
import subprocess
import sys
import tomllib
from pathlib import Path

# xcursorgen ships in xorg-xcursorgen; we run a user-local copy from
# ~/.local/bin (no sudo), and hooks/theme-set.sh may not have it on PATH.
os.environ["PATH"] = str(Path.home() / ".local/bin") + os.pathsep + os.environ.get("PATH", "")

PLUGIN_DIR = Path(__file__).resolve().parent
STATE_DIR = Path.home() / ".local/state/cursor-accent"
CONFIG_PATH = STATE_DIR / "config.json"
COLORS_PATH = Path.home() / ".local/state/omarchy/current/theme/colors.toml"
CURSOR_NAME = "Omarchy-Accent"
CURSOR_SIZE = os.environ.get("HYPRCURSOR_SIZE", "24")

SHAPE_TARGETS = {
    "modern": "Bibata-Modern-Classic",
    "original": "Bibata-Original-Classic",
}

DEFAULT_CONFIG = {"mode": "theme", "shape": "modern", "fixed_color": "#F25623"}


def load_config():
    if CONFIG_PATH.exists():
        try:
            return {**DEFAULT_CONFIG, **json.loads(CONFIG_PATH.read_text())}
        except (json.JSONDecodeError, OSError):
            pass
    return dict(DEFAULT_CONFIG)


def load_theme_colors():
    with COLORS_PATH.open("rb") as f:
        c = tomllib.load(f)
    accent = c.get("accent", "#F25623")
    body = c.get("dark_background") or c.get("background") or "#171717"
    watch = c.get("darker_background") or c.get("background") or body
    return body, accent, watch


def main():
    theme_name = sys.argv[1] if len(sys.argv) > 1 else "(unknown)"
    config = load_config()

    if config.get("mode") == "off":
        subprocess.run(["hyprctl", "setcursor", "default", CURSOR_SIZE], check=True)
        print("cursor-accent: mode=off, reverted to the system default cursor")
        return

    shape = config.get("shape", "modern")
    if shape not in SHAPE_TARGETS:
        print(f"cursor-accent: unknown shape '{shape}', falling back to modern", file=sys.stderr)
        shape = "modern"
    target = SHAPE_TARGETS[shape]

    if config.get("mode") == "fixed":
        accent = config.get("fixed_color", "#F25623")
        body = watch = "#171717"
        print(f"cursor-accent: mode=fixed shape={shape} accent={accent}")
    else:
        body, accent, watch = load_theme_colors()
        print(f"cursor-accent: mode=theme theme={theme_name} shape={shape} "
              f"body={body} accent={accent} watch={watch}")

    # Work in a scratch copy of config/, not the plugin's own tracked copy:
    # an `omarchy plugin update` mid-run shouldn't race a half-written
    # render.json, and the plugin directory should stay pristine anyway.
    STATE_DIR.mkdir(parents=True, exist_ok=True)
    # The theme-set hook, the post-boot hook, and the shell service can all
    # fire within the same second at login. Serialize them: they share the
    # scratch build dir and the install dir, and each run starts by wiping
    # both. A full build is ~0.2s, so the loser just redoes the same work.
    with (STATE_DIR / ".lock").open("w") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)

        # The post-boot hook fires on every desktop start while the theme is
        # usually unchanged, and a full build now also renders the XCursor
        # theme (tens of seconds of rsvg-convert on this box). Skip the build
        # when nothing that affects the output has changed and both the
        # hyprcursor and XCursor sets are already present; just re-apply the
        # runtime cursor (Hyprland forgets it across restarts).
        install_check = Path.home() / f".local/share/icons/{CURSOR_NAME}"
        sig = "|".join([
            str(config.get("mode")), shape, target, body, accent, watch,
            str((PLUGIN_DIR / "config/build.toml").stat().st_mtime_ns),
            str((PLUGIN_DIR / "src/cursor_utils.py").stat().st_mtime_ns),
        ])
        sig_path = STATE_DIR / "fingerprint"
        if (sig_path.exists() and sig_path.read_text().strip() == sig
                and (install_check / "cursors").is_dir()
                and (install_check / "hyprcursors").is_dir()):
            subprocess.run(["hyprctl", "setcursor", CURSOR_NAME, CURSOR_SIZE], check=True)
            print(f"cursor-accent: unchanged, re-applied {CURSOR_NAME} at size {CURSOR_SIZE}")
            return

        render_path = STATE_DIR / "render.json"
        if not render_path.exists():
            shutil.copy(PLUGIN_DIR / "config/render.json", render_path)
        render = json.loads(render_path.read_text())
        render[target]["colors"][0]["replace"] = body
        render[target]["colors"][1]["replace"] = accent
        render[target]["colors"][2]["replace"] = watch
        render_path.write_text(json.dumps(render, indent=2))

        build_dir = STATE_DIR / "build"
        shutil.rmtree(build_dir, ignore_errors=True)
        build_dir.mkdir(parents=True)
        (build_dir / "src").symlink_to(PLUGIN_DIR / "src")
        (build_dir / "svg").symlink_to(PLUGIN_DIR / "svg")
        (build_dir / "config").mkdir()
        (build_dir / "config/render.json").symlink_to(render_path)
        (build_dir / "config/build.toml").symlink_to(PLUGIN_DIR / "config/build.toml")
        (build_dir / "config/build.right.toml").symlink_to(PLUGIN_DIR / "config/build.right.toml")

        # cursor_utils.py resolves its own source paths relative to cwd, and
        # mixes those with --out-dir internally (Path.relative_to), so passing
        # an absolute --out-dir while cwd is build_dir raises "different
        # anchors". Keep it relative, matched to cwd=build_dir, to avoid that.
        # Build BOTH the hyprcursor theme (used by Hyprland itself) and the
        # XCursor theme (out/<target>/cursors, used by GTK/Qt/X apps, which
        # have no hyprcursor support) in one pass. --x11-symlink adwaita
        # emits the standard alias set (default/pointer/progress/...) so apps
        # that request those names resolve.
        subprocess.run(
            ["./src/cursor_utils.py", "--hypr", "--x11", "--x11-symlink", "adwaita",
             "--theme", target,
             "--out-dir", "out", "--log-level", "error"],
            cwd=build_dir, check=True,
        )

        install_dir = Path.home() / f".local/share/icons/{CURSOR_NAME}"
        # Install ATOMICALLY. A running Hyprland reads this directory: it loads
        # the cursor theme at startup and hyprcursor resolves shapes by name
        # lazily. The old rmtree-then-copytree left a window where the theme
        # existed but was empty/half-written; if a shape was requested then,
        # Hyprland got a NULL cairo surface and segfaulted in CCursorBuffer
        # (crash report 2026-10-09). Build the new tree fully in a sibling
        # hidden dir, then swap it in with rename(2) - atomic on the same
        # filesystem - so the theme directory is never absent or partial.
        parent = install_dir.parent
        stage_dir = parent / f".{CURSOR_NAME}.new"
        old_dir = parent / f".{CURSOR_NAME}.old"
        shutil.rmtree(stage_dir, ignore_errors=True)
        shutil.rmtree(old_dir, ignore_errors=True)
        shutil.copytree(build_dir / "out" / target, stage_dir)
        (stage_dir / "index.theme").write_text(
            "[Icon Theme]\n"
            f"Name={CURSOR_NAME}\n"
            "Comment=Bibata cursor recolored to the active Omarchy theme\n"
            "Inherits=Adwaita\n"
        )
        if install_dir.exists():
            install_dir.rename(old_dir)
        stage_dir.rename(install_dir)
        shutil.rmtree(old_dir, ignore_errors=True)
        shutil.rmtree(build_dir, ignore_errors=True)

        # Runtime-only: Hyprland forgets this on restart, and with no
        # HYPRCURSOR_THEME set it boots with whichever theme directory
        # hyprcursor finds first. The post-boot hook re-runs this script.
        subprocess.run(["hyprctl", "setcursor", CURSOR_NAME, CURSOR_SIZE], check=True)
        sig_path.write_text(sig)
        print(f"cursor-accent: applied {CURSOR_NAME} ({target}) at size {CURSOR_SIZE}")


if __name__ == "__main__":
    main()

RLR_EOF
chmod +x "$PLUGIN_DIR/recolor.py"

# ------------------------------------------------------------------- hooks
# install-cursor-hook.sh generates theme-set.d/cursor-accent.sh and
# post-boot.d/cursor-accent.sh with THIS plugin's absolute path baked in
# (omarchy-hook-install COPIES, so a static relative path would be wrong), and
# applies the current theme.
log "installing theme-set + post-boot hooks..."
bash "$PLUGIN_DIR/tools/install-cursor-hook.sh"

# ---------------------------------------------------------------- envs.lua
# Remove any HYPRCURSOR_THEME / XCURSOR_THEME (the plugin must own the theme;
# a stray env or `hyprctl setcursor` autostart line would fight it), then put
# back size-only lines. Preserves every other line in the file.
log "wiring ~/.config/hypr/envs.lua (size only, no theme env)..."
mkdir -p "$HOME/.config/hypr"
python3 - "$ENVS" "$SIZE" <<'PY'
import re, sys
from pathlib import Path
path, size = sys.argv[1], sys.argv[2]
p = Path(path)
if not p.exists():
    p.write_text("")
s = p.read_text()
s = re.sub(r'(?m)^.*\bHYPRCURSOR_THEME\b.*\n', '', s)
s = re.sub(r'(?m)^.*\bXCURSOR_THEME\b.*\n', '', s)
s = re.sub(r'(?m)^.*\bHYPRCURSOR_SIZE\b.*\n', '', s)
s = re.sub(r'(?m)^.*\bXCURSOR_SIZE\b.*\n', '', s)
if s and not s.endswith("\n"):
    s += "\n"
s += f'hl.env("HYPRCURSOR_SIZE", "{size}")\n'
s += f'hl.env("XCURSOR_SIZE", "{size}")\n'
p.write_text(s)
PY

# ------------------------------------------------------------- autostart.lua
# Drop any `hyprctl setcursor <foo>` autostart line - the post-boot hook owns
# cursor application. Keep everything else.
log "cleaning ~/.config/hypr/autostart.lua (no setcursor line)..."
python3 - "$AUTOSTART" <<'PY'
import re, sys
from pathlib import Path
path = sys.argv[1]
p = Path(path)
if not p.exists():
    p.write_text("")
s = p.read_text()
s = re.sub(r'(?m)^.*hyprctl setcursor.*\n', '', s)
p.write_text(s)
PY

# --------------------------------------------------------------- gsettings
# GTK/Qt app-level theme + size (the XCursor half xcursorgen cannot reach).
log "setting gsettings cursor theme + size..."
gsettings set org.gnome.desktop.interface cursor-theme "$CURSOR_NAME" 2>/dev/null || true
gsettings set org.gnome.desktop.interface cursor-size "$SIZE" 2>/dev/null || true

# ------------------------------------------------ session env (live, no relogin)
systemctl --user set-environment "HYPRCURSOR_SIZE=$SIZE" "XCURSOR_SIZE=$SIZE" 2>/dev/null || true
systemctl --user unset-environment HYPRCURSOR_THEME XCURSOR_THEME 2>/dev/null || true

# ------------------------------------------------------- build + apply now
export HYPRCURSOR_SIZE="$SIZE" XCURSOR_SIZE="$SIZE"
log "building + applying $CURSOR_NAME (first run slow, re-runs hit the fingerprint cache)..."
python3 "$PLUGIN_DIR/recolor.py" "$(omarchy-theme-current 2>/dev/null || echo apply)"
hyprctl reload >/dev/null 2>&1 || true

# ------------------------------------------------------------------ verify
printf '\n\033[1;36m---- cursor-accent install complete ----\033[0m\n'
echo "theme dir:   $ICONDIR"
[ -d "$ICONDIR/cursors" ]     && echo "  cursors/    : $(ls "$ICONDIR/cursors" | wc -l) entries"   || echo "  cursors/    : MISSING"
[ -d "$ICONDIR/hyprcursors" ] && echo "  hyprcursors/: $(ls "$ICONDIR/hyprcursors" | wc -l) entries" || echo "  hyprcursors/: MISSING"
echo "plugin:      $(omarchy plugin list 2>/dev/null | grep -F "$PLUGIN_ID" || echo 'run: omarchy plugin list')"
echo "xcursorgen:  $HOME/.local/bin/xcursorgen ($(test -x "$HOME/.local/bin/xcursorgen" && echo ok || echo MISSING))"
echo "fingerprint: $(test -f "$STATE_DIR/fingerprint" && echo cached || echo not-yet-built)"
for h in theme-set post-boot; do
  f="$HOME/.config/omarchy/hooks/$h.d/cursor-accent.sh"
  echo "  hook $h.d/cursor-accent.sh: $(test -x "$f" && echo ok || echo MISSING)"
done
echo "envs.lua:    $(grep -qE 'HYPRCURSOR_THEME|XCURSOR_THEME' "$ENVS" && echo 'THEME ENV PRESENT (bad)' || echo 'size only, good')"
echo "gsettings:   $(gsettings get org.gnome.desktop.interface cursor-theme 2>/dev/null || echo n/a) / size $(gsettings get org.gnome.desktop.interface cursor-size 2>/dev/null || echo n/a)"
echo "hypr errors: $(hyprctl configerrors 2>/dev/null | tr -d '\n')"
echo "NOTE: on a fresh install, reboot/login once - the post-boot hook applies on every login."
